mapper.select:
SELECT s.id, s.event_id as eventId, s.item_id as itemId, s.registration_id as registrationId, e.name as eventName, p.name as itemName, u.name as athleteName, g.name as grade, s.score_value as scoreValue, s.score_rank as scoreRank, s.is_published as isPublished, s.create_time as createTime FROM result s LEFT JOIN event e ON s.event_id = e.id LEFT JOIN event_item p ON s.item_id = p.id LEFT JOIN sys_user u ON s.user_id = u.id LEFT JOIN grade g ON u.grade_id = g.id
AND s.event_id = #{eventId}
AND s.item_id = #{itemId}
AND e.name LIKE CONCAT('%', #{eventName}, '%')
AND s.is_published = 1
ORDER BY e.id DESC, p.id ASC, s.score_rank ASC
